/* OpsTrack — the push service worker.
 *
 * WHY THIS IS A SECOND SERVICE WORKER, AND WHY IT LIVES IN ITS OWN DIRECTORY.
 * The app's main service worker is generated by vite-plugin-pwa (workbox) and
 * owns the precache and the update prompt. A service worker registration is
 * keyed by SCOPE, so registering a second script at the same scope would REPLACE
 * the workbox one and take the offline shell down with it. Sitting at
 * `<base>/push/sw.js` gives this file a default scope of `<base>/push/` — a path
 * no page ever loads — so the two registrations coexist and neither can break
 * the other. A push handler bug can never cost the app its precache, and a
 * workbox regeneration can never drop the push handler.
 *
 * It controls no clients, which is fine: `showNotification` is a method on the
 * registration and needs no controlled page, and `clients.matchAll` below asks
 * for `includeUncontrolled` precisely because of it.
 *
 * PLAIN JS, IN public/, ON PURPOSE. It must be served byte-for-byte at a stable
 * URL that is not content-hashed, and it must not import the app bundle: when a
 * push arrives there is by definition no tab open, so anything it needs has to
 * already be inside these few lines. That includes the strings — which is why
 * the sender resolves the recipient's language and ships the finished sentence
 * in the payload rather than a key this file would have to look up.
 */

// Take over from a previous version immediately. There is no state to migrate
// and no page whose behaviour could change underneath the user — this worker
// exists only to receive pushes.
self.addEventListener('install', () => self.skipWaiting())
self.addEventListener('activate', (event) => event.waitUntil(self.clients.claim()))

/** Fallback text if a push ever arrives with no body (a test from a console). */
const FALLBACK = { title: 'OpsTrack', body: '', path: '#/notifications', tag: 'opstrack' }

self.addEventListener('push', (event) => {
  let data = FALLBACK
  try {
    // `event.data` is null for a payload-less push; both branches must still show
    // something, because on every desktop browser a push that shows NO
    // notification spends one of the origin's "silent push" allowances and can
    // get the subscription revoked.
    data = event.data ? { ...FALLBACK, ...event.data.json() } : FALLBACK
  } catch {
    // Not JSON. Show the raw text rather than nothing.
    data = { ...FALLBACK, body: event.data ? event.data.text() : '' }
  }

  event.waitUntil(
    self.registration.showNotification(data.title || FALLBACK.title, {
      body: data.body,
      // Same icons the manifest ships. Relative to this file, hence the `../`.
      icon: new URL('../pwa-192.png', self.registration.scope).href,
      badge: new URL('../pwa-192.png', self.registration.scope).href,
      // One notification per inbox row: a retry replaces its own earlier banner
      // instead of stacking a duplicate on the lock screen.
      tag: data.tag || FALLBACK.tag,
      // The whole point of this feature is to interrupt, but not to startle: no
      // `requireInteraction`, so it dismisses like every other notification.
      data: { path: data.path || FALLBACK.path, id: data.id ?? null },
    }),
  )
})

/* `pushsubscriptionchange` IS DELIBERATELY NOT HANDLED HERE, and the reason is
 * structural: a browser rotates a subscription while no page is open, and this
 * worker has no session — the row lives behind RLS and needs the user's JWT, which
 * exists only inside the app. Re-subscribing from here would produce keys nothing
 * could store.
 *
 * The repair therefore lives in `loadPushState()` (src/store/push.ts): whenever the
 * settings screen opens and the browser holds a subscription this account has not
 * stored, it stores it. That closes the same hole one screen later instead of
 * pretending to close it now. */

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const path = (event.notification.data && event.notification.data.path) || FALLBACK.path
  // The app root is one level up from this worker's scope, whatever the deploy
  // path is — `/opstrack/` on GitHub Pages, `/` on a dev server. Resolving
  // against the scope is what keeps this file free of a hardcoded base URL.
  const target = new URL(`../${path}`, self.registration.scope).href

  event.waitUntil(
    (async () => {
      // `includeUncontrolled` is mandatory here: this worker controls nothing,
      // so without it the list is always empty and every click opens a new tab
      // on top of the app the user already had open.
      const clientList = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
      for (const client of clientList) {
        if (!client.url.startsWith(new URL('../', self.registration.scope).href)) continue
        await client.focus()
        // `client.navigate()` is unavailable for an uncontrolled client, so the
        // route change is asked for rather than performed. The app listens for
        // this message; if nothing is listening the user is at least focused on
        // the right window, which is the important half.
        client.postMessage({ type: 'opstrack:navigate', path })
        return
      }
      await self.clients.openWindow(target)
    })(),
  )
})
